{
  "lesson_summary": "Today's lesson plans to teach students to count up to 9999 and recognise the place value of each digit in 4-digit numbers. It will demonstrate building 9999 using cubes, flats, rods, and dots, and writing its expanded form as 9000 + 900 + 90 + 9. The lesson will also cover drawing 2015 using place value blocks and identifying the value of each digit.",
  "lesson_summary_short": "Today's lesson plans to teach counting up to 9999 and recognising the place value of each digit, using 9999 as an example.",
  "checks_summary": "This quiz checks whether the class can count 4-digit numbers, identify place values, and understand how digit position affects its value.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "Which of these is the largest 4-digit number?",
      "options": [
        "9999",
        "10000",
        "999"
      ],
      "correct_index": 0,
      "explanation": "The largest 4-digit number is 9999, as adding one more would make it a 5-digit number, 10000.",
      "selected_because": "The lesson explicitly states 9999 is the largest 4-digit number.",
      "distractor_misconceptions": {
        "1": "Confuses largest 4-digit number with smallest 5-digit number.",
        "2": "Confuses largest 4-digit number with largest 3-digit number."
      },
      "option_feedback": {
        "correct": "That's right! 9999 is the largest number you can make with four digits.",
        "wrong": {
          "1": "This number has five digits. The largest 4-digit number is 9999.",
          "2": "This number only has three digits. The largest 4-digit number is 9999."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "9999 = 9000 + 900 + 90 + 9, the largest 4-digit number",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "What is the 'place value' of the digit 9 in the number 9999?",
      "options": [
        "Thousands",
        "Hundreds",
        "Ones"
      ],
      "correct_index": 0,
      "explanation": "In the number 9999, the leftmost 9 is in the Thousands place, meaning its value is 9000.",
      "selected_because": "The lesson discusses the place value of each digit in 9999.",
      "distractor_misconceptions": {
        "1": "Confuses the Thousands place with the Hundreds place.",
        "2": "Confuses the Thousands place with the Ones place."
      },
      "option_feedback": {
        "correct": "Correct! The first 9 in 9999 is in the Thousands place.",
        "wrong": {
          "1": "The Hundreds place is for the second digit from the left. The first 9 is in the Thousands place.",
          "2": "The Ones place is for the last digit on the right. The first 9 is in the Thousands place."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Same digit, four different values 9999 = 9000 + 900 + 90 + 9",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "Which place value is ten times the value of the Ones place?",
      "options": [
        "Tens",
        "Hundreds",
        "Thousands"
      ],
      "correct_index": 0,
      "explanation": "Each place is ten times the value of the place to its right. So, the Tens place is ten times the Ones place.",
      "selected_because": "The lesson explains the relationship between adjacent place values.",
      "distractor_misconceptions": {
        "1": "Confuses the Tens place with the Hundreds place.",
        "2": "Confuses the Tens place with the Thousands place."
      },
      "option_feedback": {
        "correct": "You got it! The Tens place is indeed ten times the value of the Ones place.",
        "wrong": {
          "1": "The Hundreds place is 100 times the Ones place. The Tens place is ten times the Ones place.",
          "2": "The Thousands place is 1000 times the Ones place. The Tens place is ten times the Ones place."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Thousands, hundreds, tens, ones — each place is ten times the one on its right.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "apply",
      "question": "An atom has 6 protons. Which element is it?",
      "options": [
        "Carbon",
        "Oxygen",
        "Boron"
      ],
      "correct_index": 0,
      "explanation": "The number of protons determines the element. An atom with 6 protons is Carbon.",
      "selected_because": "This is a standard science question, not from the lesson.",
      "distractor_misconceptions": {
        "1": "Confuses Carbon with Oxygen.",
        "2": "Confuses Carbon with Boron."
      },
      "option_feedback": {
        "correct": "That's right! An atom with 6 protons is Carbon.",
        "wrong": {
          "1": "Oxygen has 8 protons. Carbon has 6 protons.",
          "2": "Boron has 5 protons. Carbon has 6 protons."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "This is a science question and not from the lesson plan.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "understand",
      "question": "What number do these blocks show?",
      "options": [
        "2015",
        "215",
        "2005"
      ],
      "correct_index": 0,
      "explanation": "The blocks show 2 Thousands blocks, 0 Hundreds flats, 1 Tens rod, and 5 Ones cubes, which represents the number 2015.",
      "selected_because": "The lesson used 2015 as an example for drawing with blocks.",
      "distractor_misconceptions": {
        "1": "Ignores the Thousands place.",
        "2": "Miscounts the Tens place as zero."
      },
      "option_feedback": {
        "correct": "Excellent! The blocks correctly show the number 2015.",
        "wrong": {
          "1": "Remember to count the Thousands blocks. There are 2 Thousands blocks, 1 Tens rod, and 5 Ones cubes, making 2015.",
          "2": "Don't forget the Tens rod! There are 2 Thousands blocks, 1 Tens rod, and 5 Ones cubes, making 2015."
        }
      },
      "figure": {
        "type": "base_ten",
        "model": "blocks",
        "thousands": 2,
        "hundreds": 0,
        "tens": 1,
        "ones": 5
      },
      "figure_role": "read_off",
      "source_quote": "Draw 2015 in the Thousands / Hundreds / Tens / Ones chart, using cubes, flats, rods and dots.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "In the number 2015, what is the value of the digit 1?",
      "options": [
        "10",
        "1",
        "100"
      ],
      "correct_index": 0,
      "explanation": "The digit 1 in 2015 is in the Tens place, so its value is 10.",
      "selected_because": "The lesson asked to write each digit's value for 2015.",
      "distractor_misconceptions": {
        "1": "Confuses the Tens place with the Ones place.",
        "2": "Confuses the Tens place with the Hundreds place."
      },
      "option_feedback": {
        "correct": "You're right! The digit 1 in 2015 is in the Tens place, which means its value is 10.",
        "wrong": {
          "1": "The digit 1 is in the Tens place, not the Ones place. Its value is 10.",
          "2": "The digit 1 is in the Tens place, not the Hundreds place. Its value is 10."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "For 2015, write each digit's place and its value.",
      "teaching_error": null
    },
    {
      "slo_id": "S1",
      "level": "apply",
      "question": "If you count on one from 2015, which place value changes first?",
      "options": [
        "Ones place",
        "Tens place",
        "Hundreds place"
      ],
      "correct_index": 0,
      "explanation": "When counting on by one, the Ones place is always the first to change.",
      "selected_because": "The lesson ended on counting on by one changing the ones place first.",
      "distractor_misconceptions": {
        "1": "Confuses the Ones place with the Tens place.",
        "2": "Confuses the Ones place with the Hundreds place."
      },
      "option_feedback": {
        "correct": "That's correct! Counting on by one always changes the Ones place first.",
        "wrong": {
          "1": "When you count on by one, the Ones place changes first, not the Tens place.",
          "2": "The Hundreds place changes much later. The Ones place changes first when counting on by one."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Counting on by one changes the ones place first.",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "How many rods are needed to show the 'Tens' part of 9999?",
      "options": [
        "9 rods",
        "90 rods",
        "900 rods"
      ],
      "correct_index": 0,
      "explanation": "The 'Tens' part of 9999 is 90. Since each rod represents 10, you need 9 rods to show 90.",
      "selected_because": "The lesson used rods to represent tens when building 9999.",
      "distractor_misconceptions": {
        "1": "Confuses the value of the digit with the number of rods.",
        "2": "Confuses the Tens place with the Hundreds place."
      },
      "option_feedback": {
        "correct": "Exactly! You need 9 rods to show 90, which is the Tens part of 9999.",
        "wrong": {
          "1": "Each rod is worth 10. To show 90, you need 9 rods, not 90 rods.",
          "2": "900 rods would be 9000. For 90, you need 9 rods."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "Build 9999 and write its expanded form 9 cubes, 9 flats, 9 rods, 9 dots",
      "teaching_error": null
    }
  ]
}
